from scipy.spatial.transform import Rotation
BASE=Path(os.environ.get('ATLAS_ANALYSIS_ROOT', 'private-analysis'));CACHE=BASE/'event-work/cache';OUT=Path(__file__).resolve().parents[1]/'dist/data';inv=pd.read_csv(BASE/'subjective-work/run_final_scores.csv');audit=[]
def direction(q):return np.stack([q[:,1],q[:,2],-q[:,0]],axis=1)
for r in inv.itertuples():
 rid=f'{r.participant}-R{r.run_index}';p=OUT/(rid+'.json');run=json.loads(p.read_text());d=dict(np.load(CACHE/r.file.replace('.ndjson','.npz')));quats=np.load(CACHE/r.file.replace('.ndjson','_head_rotation.npy')).astype(float);t=60-d['ts'];ix=np.flatnonzero(t>1e-6);ix=np.arange(max(0,ix[0]-1),len(t));ix=ix[np.r_[True,np.diff(t[ix])>1e-8]];grid=np.asarray(run['times']);hi=np.searchsorted(t[ix],grid).clip(0,len(ix)-1);lo=(hi-1).clip(0,len(ix)-1);choose=np.where(abs(t[ix[hi]]-grid)<abs(t[ix[lo]]-grid),hi,lo);qs=quats[ix[choose]];norm=np.linalg.norm(qs,axis=1);validq=np.isfinite(qs).all(axis=1)&(norm>.5)&(norm<1.5);qs[~validq]=[0,0,0,1];qs/=np.linalg.norm(qs,axis=1)[:,None];rot=Rotation.from_quat(qs)
 dirs={k:direction(rot.apply(np.tile(v,(len(qs),1)))) for k,v in [('forward',[1,0,0]),('right',[0,1,0]),('up',[0,0,1])]}
 run['headDirections']={k:[np.round(v,6).tolist() if ok and h is not None else None for v,ok,h in zip(vs,validq,run['tracks']['head'])] for k,vs in dirs.items()};run['headQuaternionUE']=[np.round(q,6).tolist() if ok else None for q,ok in zip(qs,validq)];run['orientationConvention']='Raw Unreal quaternion [x,y,z,w]; direction basis converted with position axes (no scale). Head forward is not eye gaze.'
 arrays={k:np.array([v if v is not None else [np.nan]*3 for v in run['tracks'][k]]) for k in ['left','right','vl','vr']};dp=arrays['right']-arrays['left'];dv=arrays['vr']-arrays['vl'];ps=np.linalg.norm(dp,axis=1);vs=np.linalg.norm(dv,axis=1);right=dirs['right'];horizontal=right.copy();horizontal[:,1]=0;horizontal/=np.maximum(np.linalg.norm(horizontal,axis=1)[:,None],1e-9)
 valid=np.isfinite(dp).all(axis=1)&np.isfinite(dv).all(axis=1)&validq&(ps>.1)&(vs>.1);cos=np.einsum('ij,ij->i',dp,dv)/np.maximum(ps*vs,1e-9);scale=np.einsum('ij,ij->i',dp,dv)/np.maximum(ps*ps,1e-9);headp=np.einsum('ij,ij->i',dp,horizontal);headv=np.einsum('ij,ij->i',dv,horizontal)
 # Exclude near-midline ambiguity with a 5cm margin, both world and head-relative.
 result=dict(id=rid,participant=r.participant,condition=int(r.condition),repeat=bool(r.is_favourite_run),valid_seconds=float(valid.sum()/10),physical_world_opposite_pct=float(100*np.mean(dp[valid,0]<-.05)),virtual_world_opposite_pct=float(100*np.mean(dv[valid,0]<-.05)),physical_head_opposite_pct=float(100*np.mean(headp[valid]<-.05)),virtual_head_opposite_pct=float(100*np.mean(headv[valid]<-.05)),pair_cosine_median=float(np.median(cos[valid])),pair_cosine_p01=float(np.percentile(cos[valid],1)),virtual_pair_reversed_pct=float(100*np.mean(cos[valid]<-.8)),scale_median=float(np.median(scale[valid])))
 run['channelAudit']={k:round(v,4) if isinstance(v,float) else v for k,v in result.items()};p.write_text(json.dumps(run,separators=(',',':'),allow_nan=False));audit.append(result)
a=pd.DataFrame(audit);a.to_csv(OUT/'channel_audit.csv',index=False);m=json.loads((OUT/'manifest.json').read_text());m['headOrientation']='Headset forward/right/up basis at 10Hz, nearest raw quaternion sample. Not eye gaze.';(OUT/'manifest.json').write_text(json.dumps(m,separators=(',',':')))
print(a[['physical_world_opposite_pct','physical_head_opposite_pct','virtual_pair_reversed_pct','pair_cosine_median']].describe().round(4).to_string());print(a.sort_values('virtual_pair_reversed_pct',ascending=False).head(10).to_string(index=False))
